package net.officefloor.hq.app.person;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface PersonRepository extends JpaRepository<Person, Long> {

    /** The sheet's people in the order they were added. */
    List<Person> findBySheetIdOrderByIdAsc(String sheetId);

    Optional<Person> findByIdAndSheetId(Long id, String sheetId);

    /** The sheet's person with this name or alias, ignoring case. */
    @Query("select p from Person p where p.sheetId = :sheetId and (lower(p.name) = lower(:name)"
            + " or exists (select a from PersonAlias a where a.personId = p.id and a.aliasKey = lower(:name)))")
    Optional<Person> findByName(String sheetId, String name);

    /** Whether another person on the sheet (not {@code exceptId}) has this name, ignoring case. */
    @Query("select count(p) > 0 from Person p where p.sheetId = :sheetId and lower(p.name) = lower(:name)"
            + " and (:exceptId is null or p.id <> :exceptId)")
    boolean nameInUse(String sheetId, String name, Long exceptId);

    /** Whether another person on the sheet (not {@code exceptId}) has this contact. */
    @Query("select count(p) > 0 from Person p where p.sheetId = :sheetId and p.contact = :contact"
            + " and (:exceptId is null or p.id <> :exceptId)")
    boolean contactInUse(String sheetId, String contact, Long exceptId);
}
-- A person's name is unique on the sheet, compared without regard to case and ignoring spaces
-- around it. Names are kept trimmed; name_key is the comparison form the unique index holds.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- A claim is listed under its person newest first by when it was listed there: when it was added,
-- or when it was last reassigned to them (a reassigned claim is its new person's newest).
CREATE SEQUENCE claim_listed_seq;
ALTER TABLE claim ADD COLUMN listed BIGINT DEFAULT NEXT VALUE FOR claim_listed_seq NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
-- A sheet's pools: each a name, on a sheet at most once, and its members. A member is a person of
-- the sheet with a share percent (more than 0.00, at most 100.00); a person is in a pool at most
-- once, and may be in several pools. A retired member's share counts as 0.00 toward the pool's
-- total, which the screen works out from the people as they are.
CREATE TABLE pool (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(255) NOT NULL
);
CREATE UNIQUE INDEX pool_sheet_name ON pool (sheet_id, name);

CREATE TABLE pool_member (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id BIGINT NOT NULL REFERENCES pool (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    share DECIMAL(5, 2) NOT NULL
);
CREATE UNIQUE INDEX pool_member_pool_person ON pool_member (pool_id, person_id);
-- What the screen shows as of a day: every change kept with the sheet's today when it was made, so
-- the whole sheet can be read back as it stood at the end of a past day.

-- The rest of a claim's state, kept with each state it was saved in; complete is false on the rows
-- kept before these were (their values are read from the claim as it is now).
ALTER TABLE claim_history ADD COLUMN claim_number VARCHAR(255);
ALTER TABLE claim_history ADD COLUMN opened_by VARCHAR(200);
ALTER TABLE claim_history ADD COLUMN note VARCHAR(2000);
ALTER TABLE claim_history ADD COLUMN proofs INT;
ALTER TABLE claim_history ADD COLUMN split_from VARCHAR(255);
ALTER TABLE claim_history ADD COLUMN late_entry BOOLEAN;
ALTER TABLE claim_history ADD COLUMN complete BOOLEAN DEFAULT FALSE NOT NULL;

-- Each state a person was saved in (name, terms, retirement), as of the sheet's today then.
CREATE TABLE person_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(200) NOT NULL,
    terms INT,
    retired_from DATE,
    made_on DATE NOT NULL
);
CREATE INDEX person_history_sheet ON person_history (sheet_id, person_id, id);

-- The sheet's today when the statement was taken (taken_on is the day it was taken as of); null
-- for one taken before this was kept.
ALTER TABLE statement ADD COLUMN made_on DATE;

-- The sheet's today when the patron was named; null for one named before this was kept.
ALTER TABLE person_patron ADD COLUMN made_on DATE;

-- Each time a user started or stopped watching a person, as of the sheet's today then.
CREATE TABLE person_watch_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    user_name VARCHAR(200) NOT NULL,
    watched BOOLEAN NOT NULL,
    made_on DATE NOT NULL
);
CREATE INDEX person_watch_history_sheet ON person_watch_history (sheet_id, user_name, id);

-- Each state a period was saved in, as of the sheet's today then; person_totals is each person's
-- fixed due-total as person-id=total pairs separated by commas (blank while it is open).
CREATE TABLE period_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    period_id BIGINT NOT NULL REFERENCES period (id),
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name VARCHAR(200) NOT NULL,
    from_date DATE NOT NULL,
    to_date DATE NOT NULL,
    closed BOOLEAN NOT NULL,
    soft_closed BOOLEAN NOT NULL,
    closed_total DECIMAL(12, 2),
    person_totals VARCHAR(100000) NOT NULL,
    made_on DATE NOT NULL
);
CREATE INDEX period_history_sheet ON period_history (sheet_id, period_id, id);

