-- A sheet's pot (two decimals), not dated: each member of a balanced pool shows its cut of it. Null
-- (blank) is none.
ALTER TABLE sheet ADD COLUMN pot DECIMAL(19, 2);
-- A person's aliases: other names they go by. alias_key is the alias trimmed and lower-cased, as
-- names are compared; no two aliases on a sheet share one, nor does an alias share a person's name.
CREATE TABLE person_alias (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    alias VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) NOT NULL,
    made_on DATE
);
CREATE UNIQUE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);
CREATE INDEX person_alias_person ON person_alias (person_id, id);
package net.officefloor.hq.app.statement;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    /** The sheet's statements, in the order they were taken. */
    List<Statement> findBySheetIdOrderByIdAsc(String sheetId);

    /** A person's statements, in the order they were taken. */
    List<Statement> findBySheetIdAndPersonIdOrderByIdAsc(String sheetId, Long personId);
}
